  ('TLE: AFA - Animal Production'),
  ('TLE: FCS - Food Service'),
  ('TLE: IA - Shielded Metal Arc Welding (SMAW)'),
  ('Values Education')
ON CONFLICT ((lower(btrim(name)))) DO NOTHING;

