  ('Filipino', 9, 'G9-010', 'Batas-Militar na isinulat ng mga Pilipino - Nasusuri ang mga elementong panlingguwistika (sukat, tono, tugma, at talinghaga) ng tula.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-011', 'Batas-Militar na isinulat ng mga Pilipino - Natutukoy ang mahahalagang elemento (tauhan, tagpuan, banghay na tuon sa tunggalian) at detalye sa tuluyan.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-012', 'Batas-Militar na isinulat ng mga Pilipino - Naipaliliwanag ang banghay (gaya ng pagkakasunod-sunod ng pangyayari; pagyuyugto ng mga pangyayari (foreshadowing), pagkakahanay ng mga pangyayari (parallelism and simultaneity), at pagbabalik-tanaw sa mga pangyayari (in medias res), mensahe, pahiwatig at kaisipan sa binasang tuluyan.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-013', 'Batas-Militar na isinulat ng mga Pilipino - Nasusuri ang mga elementong panlingguwistika (bisa ng salita, pahiwatig, idyomatikong pahayag, estilo) ng tuluyan.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-014', 'Batas-Militar na isinulat ng mga Pilipino - Naiuugnay ang mahahalagang kaisipan ng tula at/o tuluyan batay sa sariling pananaw, moral, katangian at karanasan ng tao.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-015', 'Batas-Militar na isinulat ng mga Pilipino - Nasusuri ang mahahalagang pangyayari sa tula at/o tuluyan batay sa konteksto ng panahon, lunan, at may-akda.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-016', 'Batas-Militar na isinulat ng mga Pilipino - Nasusuri ang kultural na elemento (simbolo, wika, norms, pagpapahalaga at arketipo) na nakapaloob sa tula at/o tuluyan batay sa konteksto ng panahon.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-017', 'Nauunawaan ang tekstong argumentatibo gamit ang mga kasanayang pang-akademiko - Mga kasanayang pang-akademiko (gaya ng pagtukoy sa paksa, layon at ideya, pagtatala ng mahahalagang impormasyon (detalye), mekaniks sa pagsulat (diksyon, estilo at paggamit ng transisyonal at kohesiyong gramatikal), paggamit ng angkop na mga salita sa pagpapahayag ng mga ideya at pagbuo ng talata)', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-018', 'Mga tekstong argumentatibo (gaya ng retorikal na analisis, literaring analisis, debate at talumpati) - Natutukoy ang paksa, layon, at ideya sa teksto.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-019', 'Mga tekstong argumentatibo (gaya ng retorikal na analisis, literaring analisis, debate at talumpati) - Natutukoy sa tekstong argumentatibo ang mga impormasyon at detalye na makatotohanan at mayaman sa opinyon.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-020', 'Mga tekstong argumentatibo (gaya ng retorikal na analisis, literaring analisis, debate at talumpati) - Nakikilala ang mga pangunahin at pangalawang sanggunian.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-021', 'Mga tekstong argumentatibo (gaya ng retorikal na analisis, literaring analisis, debate at talumpati) - Naitatala ang mahahalagang impormasyon mula sa iba’t ibang pinagkukunang sangggunian.', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-022', 'Mga tekstong argumentatibo (gaya ng retorikal na analisis, literaring analisis, debate at talumpati) - Naipaliliwanag ang mahahalagang ideya at detalye gamit ang diksyon, estilo, transisyonal at kohesiyong gramatikal at kaangkupan ng salita at ideya na nais iparating sa mambabasa. Nasusuri ang tekstong argumentatibo batay sa estruktura nito (tesis, proposisyon, datos, pangangatuwiran, at rebuttal).', 1, NULL, 'Pag-unawa at Pagsusuri sa mga Tekstong Nasusulat'),
  ('Filipino', 9, 'G9-023', 'Nasusuri ang mga tekstong biswal batay sa mga elemento - mga teknikal na biswal (laki, espasyo, kulay, linya, anyo at imahen)', 1, NULL, 'Pag-unawa at Pagsusuri ng mga Tekstong Biswal'),
