  ('Values Education', 9, 'G9-001', 'Naisasabuhay ang mapanuring pag-iisip sa pamamagitan ng pagsasaalang-alang sa impluwensiya ng pagpapahalaga sa pagpapalalim ng kamalayan sa sarili - Naiisa-isa ang mga paraan ng pagpapalalim ng kamalayan sa sarili batay sa mga pagpapahalaga', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 9, 'G9-002', 'Naisasabuhay ang mapanuring pag-iisip sa pamamagitan ng pagsasaalang-alang sa impluwensiya ng pagpapahalaga sa pagpapalalim ng kamalayan sa sarili - Naipaliliwanag na ang pagpapalalim ng kamalayan sa sarili batay sa mga pagpapahalaga ay makatutulong upang maisabuhay ang mga katangian at gawi ng lahing pinagmulan na makabubuti sa kaniyang kaganapan bilang tao', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 9, 'G9-003', 'Naisasabuhay ang mapanuring pag-iisip sa pamamagitan ng pagsasaalang-alang sa impluwensiya ng pagpapahalaga sa pagpapalalim ng kamalayan sa sarili - Naisasakilos ang mga paraan ng pagpapalalim ng kamalayan sa sarili batay sa mga pagpapahalaga', 1, '1 to 2 (10 days)', NULL),
  ('Values Education', 9, 'G9-004', 'Naisasabuhay ang matalinong pagpapasiya sa pamamagitan ng paghahanda ng sarili sa mga pangangailangan (requirements) at hamon ng pipiliing karera - Natutukoy ang mga salik sa pagpili ng karera ayon sa gabay ng pamilya', 1, '3 to 4 (10 days)', NULL),
  ('Values Education', 9, 'G9-005', 'Naisasabuhay ang matalinong pagpapasiya sa pamamagitan ng paghahanda ng sarili sa mga pangangailangan (requirements) at hamon ng pipiliing karera - Naipaliliwanag na ang mga salik sa pagpili ng karera ay dapat isasaalang-alang upang matiyak ang kahandaan sa pagpapasiya sa nais tahakin na landas sa hinaharap tungo sa matagumpay at makahulugang pamumuhay', 1, '3 to 4 (10 days)', NULL),
  ('Values Education', 9, 'G9-006', 'Naisasabuhay ang matalinong pagpapasiya sa pamamagitan ng paghahanda ng sarili sa mga pangangailangan (requirements) at hamon ng pipiliing karera - Nakalilikha ng personal na plano sa karera na may pagsasaalang-alang sa mga salik ayon sa gabay ng pamilya', 1, '3 to 4 (10 days)', NULL),
  ('Values Education', 9, 'G9-007', 'Naisasabuhay ang pagiging responsable sa pamamagitan ng paghahanda sa sarili sa mga posibleng hamon ng binubuong personal na misyon sa buhay - Nakakikilala ng mga paraan upang mabuo ang personal na misyon sa buhay ayon sa kakayahan', 1, '5 to 6 (10 days)', NULL),
  ('Values Education', 9, 'G9-008', 'Naisasabuhay ang pagiging responsable sa pamamagitan ng paghahanda sa sarili sa mga posibleng hamon ng binubuong personal na misyon sa buhay - Naipaliliwanag na ang pagbuo sa personal na misyon sa buhay ay nagbibigay-kahulugan at direksiyon na mamuhay nang makabuluhan upang itaguyod ang kabutihan at kaunlaran ng sarili at lipunan', 1, '5 to 6 (10 days)', NULL),
  ('Values Education', 9, 'G9-009', 'Naisasabuhay ang pagiging responsable sa pamamagitan ng paghahanda sa sarili sa mga posibleng hamon ng binubuong personal na misyon sa buhay - Nailalapat ang mga paraan upang mabuo ang personal na misyon sa buhay ayon sa kakayahan', 1, '5 to 6 (10 days)', NULL),
  ('Values Education', 9, 'G9-010', 'Nakapagsasanay ng integridad sa pamamagitan ng matapat na paggawa ng kaniyang tungkulin sa lahat ng pagkakataon - Nailalarawan ang paggawa na ginagabayan ng pananampalataya o paniniwala', 1, '7 to 8 (10 days)', NULL),
  ('Values Education', 9, 'G9-011', 'Nakapagsasanay ng integridad sa pamamagitan ng matapat na paggawa ng kaniyang tungkulin sa lahat ng pagkakataon - Napatutunayan na ang paggawa na may gabay ng pananampalataya o paniniwala ay moral na tungkulin bilang pakikibahagi upang makamit ang kaganapan ng kaniyang pagkatao', 1, '7 to 8 (10 days)', NULL),
  ('Values Education', 9, 'G9-012', 'Nakapagsasanay ng integridad sa pamamagitan ng matapat na paggawa ng kaniyang tungkulin sa lahat ng pagkakataon - Nailalapat ang paggawa batay sa pananampalataya o paniniwala sa mga nakaatang na gawain sa tahanan at paaralan na paghusga.', 1, '7 to 8 (10 days)', NULL),
  ('Values Education', 9, 'G9-013', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pananahimik, pagninilay, at pananalangin bago magpasiya - Natutukoy ang papel ng konsensiya sa mapanagutang pagpapasiya na nakaugat sa pananampalataya o paniniwala', 1, '9 to 10 (10 days)', NULL),
  ('Values Education', 9, 'G9-014', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pananahimik, pagninilay, at pananalangin bago magpasiya - Naipaliliwanag na ang mapanagutang pagpapasiya gabay ang pananampalataya o paniniwala ay ang maingat na paghusga ng isip na piliin ang mabuti at iwasan ang masama sa kongkretong situwasyon', 1, '9 to 10 (10 days)', NULL),
  ('Values Education', 9, 'G9-015', 'Nakapagsasanay sa maingat na paghusga sa pamamagitan ng pananahimik, pagninilay, at pananalangin bago magpasiya - Nailalapat ang mapanagutang pagpapasiya na nakaugat sa pananampalataya o paniniwala', 1, '9 to 10 (10 days)', NULL),
  ('Values Education', 9, 'G9-016', 'Naisasabuhay ang pagiging mabuting katiwala sa pamamagitan ng panghihikayat sa kapuwa na bantayan ang sariling pagkonsumo ng pagkain, damit, tubig, at kuryente sa bahay, paaralan, at pamayanan - Nakakikilala ng mga paraan ng pagbabawas ng sariling pagkonsumo ng resorses bilang pag-iingat sa kalikasan', 1, '11 (5 days)', NULL),
  ('Values Education', 9, 'G9-017', 'Naisasabuhay ang pagiging mabuting katiwala sa pamamagitan ng panghihikayat sa kapuwa na bantayan ang sariling pagkonsumo ng pagkain, damit, tubig, at kuryente sa bahay, paaralan, at pamayanan - Naipaliliwanag na ang pagbabawas ng sariling pagkonsumo ng resorses bilang pag-iingat sa kalikasan ay tungkulin ng bawat isa tungo sa pagkakaroon ng balanse, sustenable at malusog na kapaligiran', 1, '11 (5 days)', NULL),
  ('Values Education', 9, 'G9-018', 'Naisasabuhay ang pagiging mabuting katiwala sa pamamagitan ng panghihikayat sa kapuwa na bantayan ang sariling pagkonsumo ng pagkain, damit, tubig, at kuryente sa bahay, paaralan, at pamayanan - Naisasakilos ang mga paraan ng pagbabawas ng sariling pagkonsumo ng resorses bilang pag-iingat sa kalikasan', 1, '11 (5 days)', NULL),
  ('Values Education', 9, 'G9-019', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagtalima sa mga netiquette o alituntunin ng pakikipag- ugnayan sa social media - Nakapagpapahayag ng sapat at angkop na kamalayan sa pagiging mabuting digital citizen', 1, '12 (5 days)', NULL),
  ('Values Education', 9, 'G9-020', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagtalima sa mga netiquette o alituntunin ng pakikipag- ugnayan sa social media - Naipaliliwanag na ang sariling kamalayan sa pagiging mabuting digital citizen ay nakatutulong sa pagtataguyod ng kultura ng paggalang, kaligtasan, at kapayapaan sa social media', 1, '12 (5 days)', NULL),
  ('Values Education', 9, 'G9-021', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagtalima sa mga netiquette o alituntunin ng pakikipag- ugnayan sa social media - Nailalapat ang mga paraan upang mapaunlad ang sariling kamalayan sa pagiging mabuting digital citizen', 1, '12 (5 days)', NULL),
  ('Values Education', 9, 'G9-022', 'Naisasabuhay ang paggalang sa buhay sa pamamagitan ng pagsangguni sa mga wasto at pinagkakatiwalaang tao - Nakapagpapahayag ng mga paraan ng paggabay ng pamilya sa pagkilala sa sariling seksuwalidad', 1, '13 (4 days)', NULL),
  ('Values Education', 9, 'G9-023', 'Naisasabuhay ang paggalang sa buhay sa pamamagitan ng pagsangguni sa mga wasto at pinagkakatiwalaang tao - Napatutunayan na ang paggabay ng pamilya sa pagkilala sa sariling seksuwalidad ay mahalagang tungkulin bilang paghahanda sa kaakibat nitong mga katangian, gampanin, at kahihinatnan ng mga pasiya na may kaugnayan sa kaniyang pagkakakilanlan', 1, '13 (4 days)', NULL),
  ('Values Education', 9, 'G9-024', 'Naisasabuhay ang paggalang sa buhay sa pamamagitan ng pagsangguni sa mga wasto at pinagkakatiwalaang tao - Naisasakilos ang mga paraan ng pagkilala sa sariling seksuwalidad ayon sa gabay ng pamilya', 1, '13 (4 days)', NULL),
  ('Values Education', 9, 'G9-025', 'Naisasabuhay ang mapanuring pag-iisip sa pamamagitan ng paraan sa pagsunod ng pamilyang kinabibilangan sa mga batas na ayon sa likas na batas moral - Natutukoy ang mga batas na ayon sa likas na batas moral na dapat sundin ng pamilya', 2, '1 to 2 (7 days)', NULL),
  ('Values Education', 9, 'G9-026', 'Naisasabuhay ang mapanuring pag-iisip sa pamamagitan ng paraan sa pagsunod ng pamilyang kinabibilangan sa mga batas na ayon sa likas na batas moral - Naipaliliwanag na ang pagsunod ng pamilya sa mga batas na ayon sa likas na batas moral ay paraan ng pagsusulong ng dignidad, kapayapaan at katarungan tungo sa pagpapatatag ng lipunan', 2, '1 to 2 (7 days)', NULL),
  ('Values Education', 9, 'G9-027', 'Naisasabuhay ang mapanuring pag-iisip sa pamamagitan ng paraan sa pagsunod ng pamilyang kinabibilangan sa mga batas na ayon sa likas na batas moral - Nailalapat ang wastong pagtatasa ng mga batas batay sa kaangkupan nito sa dignidad ng tao', 2, '1 to 2 (7 days)', NULL),
  ('Values Education', 9, 'G9-028', 'Nakapagsasanay ng pagiging mapagpasensiya sa pamamagitan ng pagtutuon ng pansin sa paglutas ng suliranin o pakikipagkasundo upang maiwasang lumala ang situwasyon - Nakakikilala ng mga paraan sa pagtugon sa mga suliranin sa kapuwa', 2, '3 (5 days)', NULL),
  ('Values Education', 9, 'G9-029', 'Nakapagsasanay ng pagiging mapagpasensiya sa pamamagitan ng pagtutuon ng pansin sa paglutas ng suliranin o pakikipagkasundo upang maiwasang lumala ang situwasyon - Naipaliliwanag na ang pagtugon sa mga suliranin sa kapuwa ay pagpapanatili ng mapayapa at positibong ugnayan gamit ang mapanagutang pagpapasiya at maayos na pangangasiwa ng emosyon', 2, '3 (5 days)', NULL),
  ('Values Education', 9, 'G9-030', 'Nakapagsasanay ng pagiging mapagpasensiya sa pamamagitan ng pagtutuon ng pansin sa paglutas ng suliranin o pakikipagkasundo upang maiwasang lumala ang situwasyon - Naisasakilos ang sariling paraan ng pagtugon sa mga suliranin sa kapuwa', 2, '3 (5 days)', NULL),
  ('Values Education', 9, 'G9-031', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagsunod sa alintuntunin ng pamayanan, pag-aaral nang mabuti, at paggawa ng tungkulin sa lipunang kinabilangan - Natutukoy ang mga pansariling gampanin bilang isang mapanagutang namumuno at tagasunod', 2, '4 to 5 (8 days)', NULL),
  ('Values Education', 9, 'G9-032', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagsunod sa alintuntunin ng pamayanan, pag-aaral nang mabuti, at paggawa ng tungkulin sa lipunang kinabilangan - Nahihinuha na ang pansariling gampanin bilang isang mapanagutang namumuno at tagasunod ay hakbang sa pagdidisiplina sa sarili tungo sa pagpapabuti ng lipunan upang umiral ang kabutihang panlahat', 2, '4 to 5 (8 days)', NULL),
  ('Values Education', 9, 'G9-033', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagsunod sa alintuntunin ng pamayanan, pag-aaral nang mabuti, at paggawa ng tungkulin sa lipunang kinabilangan - Nailalapat ang mga pansariling gampanin bilang isang mapanagutang namumuno at tagasunod', 2, '4 to 5 (8 days)', NULL),
  ('Values Education', 9, 'G9-034', 'Naisasabuhay ang kapayapaan sa pamamagitan ng pagpili at paglahok sa mga positibong gawain na nagdudulot ng panloob na kapayapaan - Nakakikilala ng mga wastong pagtugon ng pamilya laban sa karahasan', 2, '6 (5 days)', NULL),
  ('Values Education', 9, 'G9-035', 'Naisasabuhay ang kapayapaan sa pamamagitan ng pagpili at paglahok sa mga positibong gawain na nagdudulot ng panloob na kapayapaan - Nasusuri na ang pagtugon ng pamilya laban sa karahasan ay makatutulong sa pagpapanatili ng kapayapaan at katiwasayan sa tahanan bilang pagkilala sa taglay nilang dignidad', 2, '6 (5 days)', NULL),
  ('Values Education', 9, 'G9-036', 'Naisasabuhay ang kapayapaan sa pamamagitan ng pagpili at paglahok sa mga positibong gawain na nagdudulot ng panloob na kapayapaan - Naisasakilos ang pagsusulong ng mga paraan aupang maiwasan ang karahasan', 2, '6 (5 days)', NULL),
  ('Values Education', 9, 'G9-037', 'Naisasabuhay ang pagiging madasalin sa pamamagitan ng paglalaan ng oras o panahon upang makapag-isa, manahimik, at manalangin - Natutukoy ang mga kabutihang dulot at paghahanda sa panahon ng pag-iisa, pananahimik, at pananalangin sa tulong ng pamilya', 2, '7 to 8 (8 days)', NULL),
  ('Values Education', 9, 'G9-038', 'Naisasabuhay ang pagiging madasalin sa pamamagitan ng paglalaan ng oras o panahon upang makapag-isa, manahimik, at manalangin - Napatutunayan na ang paglalaan ng panahon sa pag-iisa, pananahimik, at pananalangin sa tulong ng pamilya ay nakatutulong upang magkaroon ng malalim na ugnayan sa Diyos at positibong pananaw sa buhay', 2, '7 to 8 (8 days)', NULL),
  ('Values Education', 9, 'G9-039', 'Naisasabuhay ang pagiging madasalin sa pamamagitan ng paglalaan ng oras o panahon upang makapag-isa, manahimik, at manalangin - Naisasakilos ang paglalaan ng panahon sa pag-iisa, pananahimik, at pananalangin sa tulong ng pamilya', 2, '7 to 8 (8 days)', NULL),
  ('Values Education', 9, 'G9-040', 'Naisasabuhay ang pananampalataya sa mga gawi ng pamilya na nakatutulong upang mapalalim ang ugnayan sa Diyos - Naiisa-isa ang mga gawi ng pamilya sa pagpapalalim ng pananampalataya', 2, '9 to 10 (8 days)', NULL),
  ('Values Education', 9, 'G9-041', 'Naisasabuhay ang pananampalataya sa mga gawi ng pamilya na nakatutulong upang mapalalim ang ugnayan sa Diyos - Nahihinuha na ang pag-unawa sa mga gawi ng pamilya sa pagpapalalim ng pananampalataya ay nakatutulong upang mapanatili at mapatatag ang ugnayan ng pamilya sa Diyos at ang buhay espirituwal sa kabuuan', 2, '9 to 10 (8 days)', NULL),
  ('Values Education', 9, 'G9-042', 'Naisasabuhay ang pananampalataya sa mga gawi ng pamilya na nakatutulong upang mapalalim ang ugnayan sa Diyos - Nailalapat ang mga gawi ng pamilya sa pagpapalalim ng pananampalataya', 2, '9 to 10 (8 days)', NULL),
  ('Values Education', 9, 'G9-043', 'Naisasabuhay ang pagiging mabuting katiwala sa pamamagitan ng palagiang pakikilahok sa mga gawaing pangkapaligiran ng pamilya - Nakakikilala ng mga pananagutan ng pamilya sa pangangalaga at pagpapayaman ng kalikasan', 2, '11 (5 days)', NULL),
  ('Values Education', 9, 'G9-044', 'Naisasabuhay ang pagiging mabuting katiwala sa pamamagitan ng palagiang pakikilahok sa mga gawaing pangkapaligiran ng pamilya - Napatutunayan na ang pananagutan ng pamilya sa pangangalaga at pagpapayaman ng kalikasan ay mahalagang gampanin ng bawat isa upang matiyak ang balanse at sustenableng kalagayan nito', 2, '11 (5 days)', NULL),
  ('Values Education', 9, 'G9-045', 'Naisasabuhay ang pagiging mabuting katiwala sa pamamagitan ng palagiang pakikilahok sa mga gawaing pangkapaligiran ng pamilya - Naisasakilos ang mga sariling paraan ng pananagutan ng pamilya sa pangangalaga at pagpapayaman ng kalikasan', 2, '11 (5 days)', NULL),
  ('Values Education', 9, 'G9-046', 'Nakapagsasanay ng pagiging mapanagutan sa pamamagitan ng pagsasabuhay ng pagkakaisa sa pamilya - Natutukoy ang mga katangian ng pamilya na nagtataglay ng pagkakaisa tungo sa maunlad na lipunan', 2, '12 (5 days)', NULL),
  ('Values Education', 9, 'G9-047', 'Nakapagsasanay ng pagiging mapanagutan sa pamamagitan ng pagsasabuhay ng pagkakaisa sa pamilya - Napatutunayan na ang pagsasabuhay ng pagkakaisa ng pamilya tungo sa maunlad na lipunan ay daan sa pagpapaunlad ng sarili at pagkamit ng kabutihang panlahat', 2, '12 (5 days)', NULL),
  ('Values Education', 9, 'G9-048', 'Nakapagsasanay ng pagiging mapanagutan sa pamamagitan ng pagsasabuhay ng pagkakaisa sa pamilya - Nailalapat ang mga sariling gawi ng pagkakaisa tungo sa maunlad na lipunan', 2, '12 (5 days)', NULL),
  ('Values Education', 9, 'G9-049', 'Nakapagsasanay sa kahusayan sa pamamagitan ng palagiang pagsasakilos at pagpapaunlad ng taglay na kakayahan at kasanayan - Natutukoy ang mga paraan upang makamit ang kagalingan sa paggawa kaakibat ang positibong pakikipag-ugnayan sa kapuwa', 2, '13 to 14 (8 days)', NULL),
  ('Values Education', 9, 'G9-050', 'Nakapagsasanay sa kahusayan sa pamamagitan ng palagiang pagsasakilos at pagpapaunlad ng taglay na kakayahan at kasanayan - Naipaliliwanag na ang kagalingan sa paggawa kaakibat ang positibong pakikipag-ugnayan sa kapuwa ay magbubunsod na abutin ang mataas na kalidad ng produkto o gawain habang yumayabong ang samahan o relasyon sa iba', 2, '13 to 14 (8 days)', NULL),
  ('Values Education', 9, 'G9-051', 'Nakapagsasanay sa kahusayan sa pamamagitan ng palagiang pagsasakilos at pagpapaunlad ng taglay na kakayahan at kasanayan - Naisasakilos ang sariling paraan upang makamit ang kagalingan sa paggawa kaakibat ang positibong pakikipag-ugnayan sa kapuwa', 2, '13 to 14 (8 days)', NULL),
  ('Values Education', 9, 'G9-052', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pagsasaalang-alang sa kultura ng kapuwa sa mga gawaing pampaaralan o pampamayanan - Naiisa-isa ang mga paraan ng pagtanggap sa pagkakaiba-iba ng kultura ng kapuwa', 2, '15 (4 days)', NULL),
  ('Values Education', 9, 'G9-053', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pagsasaalang-alang sa kultura ng kapuwa sa mga gawaing pampaaralan o pampamayanan - Naipaliliwanag na ang pagtanggap sa pagkakaiba-iba ng kultura ng kapuwa ay pagkilala sa dignidad ng kapuwa na magpapanatili ng mabuting pakikipag-ugnayan sa kanila at magbubunga ng katiwasayan para sa lahat', 2, '15 (4 days)', NULL),
  ('Values Education', 9, 'G9-054', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pagsasaalang-alang sa kultura ng kapuwa sa mga gawaing pampaaralan o pampamayanan - Naisasakilos ang mga paraan ng pagtanggap sa pagkakaiba-iba ng kultura ng kapuwa', 2, '15 (4 days)', NULL),
  ('Values Education', 9, 'G9-055', 'Naisasabuhay ang pananalig sa Diyos sa pamamagitan ng palagiang pakikilahok sa pangkatang pagdarasal o gawaing pagsamba upang lalong lumalim ang pananamapalataya o paniniwala - Nakakikilala ng mga paraan ng pagpapalalim ng pananampalataya katuwang ang kapuwa', 3, '1 (5 days)', NULL),
  ('Values Education', 9, 'G9-056', 'Naisasabuhay ang pananalig sa Diyos sa pamamagitan ng palagiang pakikilahok sa pangkatang pagdarasal o gawaing pagsamba upang lalong lumalim ang pananamapalataya o paniniwala - Naipaliliwanag na ang pagpapalalim ng pananampalataya katuwang ang kapuwa ay pagtitiyak na laging may pag-asa na malalampasan ang mga hamon ng buhay nang hindi nag-iisa', 3, '1 (5 days)', NULL),
  ('Values Education', 9, 'G9-057', 'Naisasabuhay ang pananalig sa Diyos sa pamamagitan ng palagiang pakikilahok sa pangkatang pagdarasal o gawaing pagsamba upang lalong lumalim ang pananamapalataya o paniniwala - Nailalapat ang mga wastong paraan ng pakikapag- ugnayan sa kapuwa sa kabila ng nagtutunggaliang paniniwala o relihiyon', 3, '1 (5 days)', NULL),
  ('Values Education', 9, 'G9-058', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng panghihikayat sa iba na kilalanin na may kaugnayan ang Diyos sa lahat ng natatamong tulong mula sa kapuwa - Nakapagpapahayag ng iba’t ibang anyo ng pasasalamat sa Diyos para sa kabutihang naidulot ng kapuwa', 3, '2 to 3 (8 days)', NULL),
  ('Values Education', 9, 'G9-059', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng panghihikayat sa iba na kilalanin na may kaugnayan ang Diyos sa lahat ng natatamong tulong mula sa kapuwa - Nahihinuha na ang iba’t ibang anyo ng pasasalamat sa Diyos para sa kabutihang naidulot ng kapuwa ay nagbibigay ng pagkakataon upang maging biyaya sa ibang tao bilang pagkilala na ang lahat ng bagay ay mula sa Kaniya', 3, '2 to 3 (8 days)', NULL),
  ('Values Education', 9, 'G9-060', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng panghihikayat sa iba na kilalanin na may kaugnayan ang Diyos sa lahat ng natatamong tulong mula sa kapuwa - Naisasakilos ang paraan ng pasasalamat sa Diyos para sa kabutihang naidulot ng kapuwa', 3, '2 to 3 (8 days)', NULL)
) AS v(area, grade_level, lc_code, competency_text, term, week, domain)
JOIN procurements.sms_learning_areas a ON lower(btrim(a.name)) = lower(btrim(v.area))
ON CONFLICT (learning_area_id, grade_level, lc_code) DO NOTHING;

/* Verification: after all 22 parts, seeded_entries = 6718. */
SELECT count(*) AS seeded_entries,
       count(DISTINCT learning_area_id) AS learning_areas
FROM procurements.sms_competency_catalogue
WHERE lc_code ~ '^(K|G[0-9]+)-[0-9]{3}$';
